(()=>{
const U='https://fzqpmpgbubpmongodcat.supabase.co',K='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZ6cXBtcGdidWJwbW9uZ29kY2F0Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc5NzI5MzIsImV4cCI6MjEwMzU0ODkzMn0.pLJfo5jpfMNRQCAbKC1dEW_INuBJan_eoyB_hWpChdw';
let qrs={attendee:'',dj:''},loaded=false;
const headers={'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json'};
async function load(){try{const r=await fetch(U+'/rest/v1/rpc/get_panel_qrs',{method:'POST',headers,body:'{}'});const j=await r.json();const row=Array.isArray(j)?(j[0]||{}):(j||{});qrs={attendee:row.attendee_qr_image||'',dj:row.dj_qr_image||''};loaded=true;mount();}catch{loaded=true;}}
let toastTimer;function toast(text){let t=document.getElementById('rc-panel-qr-toast');if(!t){t=document.createElement('div');t.id='rc-panel-qr-toast';t.style.cssText='position:fixed;inset:0;z-index:12000;display:grid;place-items:center;pointer-events:none;';const b=document.createElement('div');b.style.cssText='padding:13px 20px;border:1px solid rgba(108,239,255,.7);border-radius:14px;background:rgba(8,8,18,.94);box-shadow:0 0 28px rgba(108,239,255,.3);color:#fff;font-size:14px;font-weight:900;';t.appendChild(b);document.body.appendChild(t)}t.firstElementChild.textContent=text;t.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{t.style.opacity='0';},3000)}function download(src,name){const a=document.createElement('a');a.href=src;a.download=name+'.png';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();toast('QR descargado');}
function addQr(card,src,label,name){if(!src||card.querySelector('.rc-panel-qr'))return;const box=document.createElement('div');box.className='rc-panel-qr';box.style.cssText='display:flex;align-items:center;gap:12px;margin-top:18px;padding-top:14px;border-top:1px solid rgba(255,255,255,.12);font-size:12px;color:rgba(255,255,255,.65);';const img=document.createElement('img');img.src=src;img.alt=label;img.style.cssText='width:72px;height:72px;object-fit:contain;background:#fff;border-radius:9px;padding:4px;';const info=document.createElement('div');info.style.cssText='display:grid;gap:7px;min-width:0;';const title=document.createElement('strong');title.textContent=label;title.style.cssText='color:#6cefff;font-size:12px;';const btn=document.createElement('span');btn.textContent='Descargar QR';btn.style.cssText='display:inline-flex;width:max-content;cursor:pointer;border:1px solid rgba(255,55,211,.65);border-radius:9px;padding:6px 9px;color:#fff;background:rgba(255,55,211,.18);font-weight:800;';btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();download(src,name)});info.append(title,btn);box.append(img,info);card.appendChild(box);}
function mountUsers(){if(!loaded)return;document.querySelectorAll('button').forEach(card=>{const t=(card.textContent||'').trim();if(/Entrar como Asistente|Enter as Attendee/i.test(t))addQr(card,qrs.attendee,'QR del asistente','qr-asistente');else if(/Panel de DJ|DJ Panel/i.test(t))addQr(card,qrs.dj,'QR del Panel DJ','qr-panel-dj');});}
function readImage(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');const r=new FileReader();r.onerror=reject;r.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const max=900,scale=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/webp',.86));};im.src=r.result;};r.readAsDataURL(file);});}
function session(){try{return JSON.parse(sessionStorage.getItem('rc_music_dj_session_v1')||localStorage.getItem('rc_music_dj_session_v1')||'null')}catch{return null}}
async function savePanelQrs(a,d,msg){const s=session(),token=s?.token;if(!token){msg.textContent='Ingresa como desarrollador para guardar los QR.';return}msg.textContent='Guardando…';try{const r=await fetch(U+'/rest/v1/rpc/admin_set_panel_qrs',{method:'POST',headers,body:JSON.stringify({p_token:token,p_attendee_qr:a,p_dj_qr:d})});if(!r.ok)throw Error();qrs={attendee:a,dj:d};msg.textContent='QR actualizados correctamente.';mountUsers();}catch{msg.textContent='No se pudieron guardar los QR.'}}
function mountAdmin(){const root=document.querySelector('div[class*="z-[11000]"]');if(!root||root.querySelector('#rc-panel-qr-manager'))return;const h=[...root.querySelectorAll('h2')].find(x=>/Centro de gestión/i.test(x.textContent||''));if(!h)return;const control=[...root.querySelectorAll('button')].find(x=>/Control de clientes/i.test(x.textContent||''));const controlWrap=control?.parentElement;const target=controlWrap?.parentElement||root.firstElementChild||root;const box=document.createElement('section');box.id='rc-panel-qr-manager';box.style.cssText='margin:16px 0;padding:16px;border:1px solid rgba(218,0,255,.35);border-radius:18px;background:rgba(218,0,255,.07);';const head=document.createElement('button');head.type='button';head.style.cssText='display:flex;align-items:center;justify-content:space-between;width:100%;padding:0;background:none;border:0;color:#f0b8ff;cursor:pointer;text-align:left;';const title=document.createElement('h3');title.textContent='QR de los paneles';title.style.cssText='margin:0;font-size:16px;font-weight:900;';const plus=document.createElement('span');plus.textContent='+';plus.style.cssText='display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(108,239,255,.8);border-radius:50%;font-size:25px;line-height:1;color:#6cefff;';head.append(title,plus);const content=document.createElement('div');content.style.cssText='margin-top:14px;';content.hidden=true;head.onclick=()=>{content.hidden=!content.hidden;plus.textContent=content.hidden?'+':'−';};const desc=document.createElement('p');desc.textContent='Sube o reemplaza los QR que verán los usuarios en las tarjetas de Asistente y Panel DJ.';desc.style.cssText='margin:0 0 14px;font-size:12px;color:rgba(255,255,255,.58);';const grid=document.createElement('div');grid.style.cssText='display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));';const a=field('QR de Asistente',qrs.attendee),d=field('QR de Panel DJ',qrs.dj);const save=document.createElement('button');save.type='button';save.textContent='Guardar QR';save.style.cssText='margin-top:12px;border:0;border-radius:10px;padding:10px 14px;background:#da00ff;color:#fff;font-weight:900;cursor:pointer;';const msg=document.createElement('p');msg.style.cssText='margin:9px 0 0;font-size:12px;color:#6cefff;';save.onclick=async()=>{const av=await readImage(a.input.files?.[0])||qrs.attendee,dv=await readImage(d.input.files?.[0])||qrs.dj;await savePanelQrs(av,dv,msg)};grid.append(a.wrap,d.wrap);content.append(desc,grid,save,msg);box.append(head,content);if(controlWrap)target.insertBefore(box,controlWrap);else target.appendChild(box);function field(label,src){const wrap=document.createElement('label');wrap.style.cssText='display:grid;gap:7px;padding:10px;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:rgba(0,0,0,.15);font-size:12px;font-weight:800;color:#fff;';const name=document.createElement('span');name.textContent=label;const img=document.createElement('img');img.src=src||'';img.alt=label;img.style.cssText='width:76px;height:76px;object-fit:contain;background:#fff;border-radius:8px;padding:4px;'+(src?'':'display:none');const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';wrap.append(name,img,input);return {wrap,input}}}
function mount(){mountUsers();mountAdmin()}
new MutationObserver(()=>mount()).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('rc-panel-qrs-updated',load);load();
})();